{
  "description": "A low, quadrupedal creature is shown in right-facing profile against a plain light background. It has a broad, flat, pale pinkish-tan head with large round eyes and a blunt snout, with six feathery reddish external gills projecting from behind the head. Its ventral body, neck, limbs and tail underside are pale, moist-looking, and deeply wrinkled with transverse folds, while its entire dorsal surface from the neck to the base of the tail is covered in overlapping large brown scales. It stands on four short, thick, fleshy limbs with splayed clawed feet, and a long thick tapering tail extends to the left rear, scaly on top and fleshy below.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flattened and blunt-snouted, pale pinkish-tan with moist, slightly bumpy skin, small round nostrils at the tip of the snout, large round eyes with golden-brown iris, dark pupil and pale blue-grey outer ring, and a closed mouth with a slight smile",
      "where": "at the anterior right end of the body, in front of the gills and above the forelegs"
    },
    {
      "part": "gills",
      "looks_like": "six feathery external gills, reddish-brown with a central stalk and many fine filamentous branches on both sides, fleshy at the base",
      "where": "three projecting from each side of the head-neck junction, curving outward and backward, behind and to the sides of the head"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, rounded keratinous scales, brown with darker brown margins and lighter tan centers, with fine concentric ridges, arranged in diagonal rows",
      "where": "covering the entire dorsal back, sides and top of the tail base, from just behind the gills to the mid-tail, meeting the pale ventral skin along the flank"
    },
    {
      "part": "plates",
      "looks_like": "same as scales - large overlapping brown plates with darker edges forming an armor-like covering",
      "where": "dorsal surface as described for scales"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, stout limbs with pale pink wrinkled fleshy skin, visible elbow and knee bends, muscular upper segments tapering to the feet",
      "where": "two forelegs under the chest and two hindlegs under the mid-body, supporting the body low above the ground"
    },
    {
      "part": "feet",
      "looks_like": "four splayed feet with five short digits each, tipped with small dark brown claws, skin wrinkled and pale pink, soles flat on the ground",
      "where": "at the distal end of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick, tapering tail, dorsal side covered in the same brown scales as the back, ventral and lateral sides pale pink with wrinkled skin and transverse folds",
      "where": "extending posteriorly to the left from the rear of the body, tip going out of the left edge of the image"
    },
    {
      "part": "markings",
      "looks_like": "subtle mottled grey-brown speckling on the top of the head and neck, and transverse wrinkled folds and creases along the pale ventral torso and limbs; no distinct spots or stripes",
      "where": "on the dorsal head, neck, and along the pale underbody and limbs"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
